#!/bin/bash
sudo python3 - /var/lib/bench50335957/bundle/config.json <<'PY'
import json, sys
p = sys.argv[1]
c = json.load(open(p))
for m in c['mounts']:
    if m['destination'] == '/test-proc':
        m.update({'type': 'proc', 'source': 'proc', 'options': ['nosuid', 'nodev', 'noexec', 'ro']})
json.dump(c, open(p, 'w'), indent=2)
